import Foundation
import Crypto
import XCTest

/// Loads the JSON copy of `contracts/openapi.yaml` (generated by `scripts/contract-json.sh`) and checks it is not stale.
enum Contract {
    static let directory = URL(fileURLWithPath: #filePath).deletingLastPathComponent()
    static let repositoryRoot = directory.deletingLastPathComponent().deletingLastPathComponent().deletingLastPathComponent()

    static func load() throws -> [String: Any] {
        let data = try Data(contentsOf: directory.appendingPathComponent("openapi.contract.json"))
        let document = try XCTUnwrap(JSONSchemaValidator.parse(data) as? [String: Any])
        let yaml = try Data(contentsOf: repositoryRoot.appendingPathComponent("contracts/openapi.yaml"))
        let digest = SHA256.hash(data: yaml).map { String(format: "%02x", $0) }.joined()
        guard document["x-source-sha256"] as? String == digest else {
            throw ContractStale()
        }
        return document
    }

    struct ContractStale: Error, CustomStringConvertible {
        var description: String { "Tests/TimetrackKitTests/Contract/openapi.contract.json is stale: run scripts/contract-json.sh and commit the result." }
    }

    /// `{id}`-style parameters collapse to `{}` so differently named parameters compare equal.
    static func normalise(_ path: String) -> String {
        path.split(separator: "/", omittingEmptySubsequences: true).map { $0.hasPrefix("{") ? "{}" : String($0) }.joined(separator: "/")
    }

    static func operations(_ document: [String: Any]) -> [String: [String: Any]] {
        var result: [String: [String: Any]] = [:]
        let methods: Set<String> = ["get", "put", "post", "delete", "patch", "head", "options"]
        for (path, item) in document["paths"] as? [String: Any] ?? [:] {
            for (method, operation) in item as? [String: Any] ?? [:] where methods.contains(method) {
                result[method.uppercased() + " /" + normalise(path)] = operation as? [String: Any] ?? [:]
            }
        }
        return result
    }
}

extension Contract {
    /// JSON schema documented for `status` of `method` on the contract path `template` (response `$ref`s resolved), if any.
    static func responseSchema(_ document: [String: Any], method: String, template: String, status: Int) -> (found: Bool, schema: [String: Any]?) {
        guard let item = (document["paths"] as? [String: Any])?[template] as? [String: Any],
              let operation = item[method.lowercased()] as? [String: Any],
              var response = (operation["responses"] as? [String: Any])?[String(status)] as? [String: Any] else { return (false, nil) }
        if let ref = response["$ref"] as? String {
            let name = ref.split(separator: "/").last.map(String.init) ?? ""
            response = ((document["components"] as? [String: Any])?["responses"] as? [String: Any])?[name] as? [String: Any] ?? [:]
        }
        let schema = ((response["content"] as? [String: Any])?["application/json"] as? [String: Any])?["schema"] as? [String: Any]
        return (true, schema)
    }
}
